def main():
    stem = 'enchantment_rank6'
    draft = A / 'ENCHANTMENT_RANK6_OPERATING_PROPOSALS.json'
    out = R / f'data/director/spell_proposals/{stem}.json'
    doc = R / 'docs/spells/proposals/ENCHANTMENT_RANK6.md'
    receipt = A / 'ENCHANTMENT_RANK6_OPERATING_PROPOSAL_CHECK.json'
    assert not any(p.exists() for p in [draft, out, doc, receipt]), 'One-use authoring: preserve prior outputs'
    prep_path = A / 'ENCHANTMENT_RANK6_SOURCE_PREPARATION.json'
    prep = read(prep_path)
    selected = {s['spellId']: s for s in prep['selectedSpells'] if s['scope'] == 'pre-push mechanical source question'}
    deferred = [s for s in prep['selectedSpells'] if s['scope'] == 'post-push receipt only']
    cat_path = R / 'data/public/spell_playtests/catalog.json'
    idx_path = cat_path.with_name('authored_review_index.json')
    core_path = R / 'data/public/Decennium_Descent_Core_Systems_Data_v2_Known_Descent.json'
    cat, idx, core = read(cat_path), read(idx_path), read(core_path)
    catalog = {x['id']: x for x in cat['spells']}
    entries = {x['id']: x for x in idx['entries']}
    inputs = {prep_path, cat_path, idx_path, core_path, Path(__file__).resolve()}
    checks = []
    def check(name, result):
        checks.append({'name': name, 'pass': bool(result)})
        assert result, name
    check('Seven mechanical procedures and one untouched post-push receipt', len(P) == len(selected) == 7 and {p['spellId'] for p in P} == set(selected) and len(deferred) == 1)
    check('Catalog remains848 with412 reviewed and436 pending', len(catalog) == 848 and idx['authoredCounts'] == {'reviewed': 412, 'pending': 436})
    check('Actual Wizard11 RP maximum40 and Mage11 maximum32', core['caster_pools']['Wizard'][10] == 40 and core['caster_pools']['Mage'][10] == 32)
    records = []
    for p in P:
        sid = p['spellId']; s = selected[sid]; f = catalog[sid]
        digest = sha256(json.dumps(f, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
        check(sid + ' complete original source/access retained', f == s['fullSourceAndCurrentAccessRecord'] and digest == s['recordSha256'])
        check(sid + ' no ordinary spell promotion', f['operational'] is None and entries[sid]['authoredStatus'] == 'pending-authored-procedure')
        check(sid + ' actual rank6/base13 access retained', all(a['rank'] == 6 and a['baseRpCost'] == 13 for a in f['classAccess'].values()))
        check(sid + ' complete procedure/two examples/new choices', len(p['procedure']) > 1900 and len(p['workedCases']) == 2 and all(len(c) > 280 for c in p['workedCases']) and p['newChoices'].startswith('NEW'))
        for e in f['source']['coreEntries'] + f['source']['possibleHistoricalAliases']:
            check(sid + ' whole Core source at ' + str(e['index']), core['spells'][e['index']] == e['original'])
        records.append({**p, 'questionId': s['questionId'], 'originalQuestion': s['individualQuestion'], 'fullSourceAndCurrentAccessRecord': f,
                        'sourceRecordSha256': digest, 'status': 'unadopted-unsent-operating-proposal', 'examplesAreRuntimeTests': False})
    check('Both Mental Prison placements preserved', {e['original']['school'] for e in catalog['mental-prison']['source']['coreEntries']} == {'Enchantment', 'Illusion'})
    check('Mass Suggestion duration conflict preserved', {e['original']['duration'] for e in catalog['mass-suggestion']['source']['coreEntries']} == {'24 hours', 'Instantaneous'})
    check('Haze original30foot range preserved', catalog['haze-of-forgetting']['source']['coreEntries'][0]['original']['range'] == '30 feet')
    for d in deferred:
        sid = d['spellId']; f = catalog[sid]
        check(sid + ' literal deferred source unchanged', f == d['fullSourceAndCurrentAccessRecord'] and f['operational'] is None and sid not in {r['spellId'] for r in records})
        for e in f['source']['coreEntries']:
            check(sid + ' complete Core receipt at ' + str(e['index']), core['spells'][e['index']] == e['original'])
    check('Soul Cage remains two distinct source placements', len(catalog['soul-cage']['source']['coreEntries']) == 2)
    cids = sorted({x['id'] for x in prep['completeCounterparts']} | {'disrupt-memory', 'mental-chains', 'antimagic-field-lesser', 'quicken-cast'})
    counterparts = []
    for sid in cids:
        e = entries[sid]; p = cat_path.parent / e['procedureFile']; d = read(p); inputs.add(p)
        for key in e['wholeCardPointer'].strip('/').split('/'):
            d = d[int(key)] if isinstance(d, list) else d[key]
        check(sid + ' whole current counterpart identity', d.get('id', d.get('spellId')) == sid)
        op = d.get('operational', d.get('operationalCandidate'))
        check(sid + ' true current reviewed/pending status', (e['authoredStatus'] == 'reviewed-authored-operational-playtest' and isinstance(op, dict)) or (e['authoredStatus'] == 'pending-authored-procedure' and d.get('operational') is None))
        counterparts.append({'id': sid, 'completePreparedComparisonOccurrences': [x for x in prep['completeCounterparts'] if x['id'] == sid],
                             'additionalControlInterfaceComparison': sid in {'disrupt-memory', 'mental-chains', 'antimagic-field-lesser', 'quicken-cast'}, 'currentSourceCatalogRecord': catalog[sid],
                             'currentAuthoredIndexEntry': e, 'completeCurrentAuthoredRecord': d})
    pending = {sid for sid in cids if entries[sid]['authoredStatus'] == 'pending-authored-procedure'}
    check('Fifteen whole current counterparts: eight reviewed/seven pending', len(counterparts) == 15 and len(pending) == 7)
    earlier = []
    for stem in ['divination_universal_rank5', 'enchantment_illusion_rank5', 'divination_enchantment_rank4', 'abjuration_conjuration_rank5']:
        p = R / f'data/director/spell_proposals/{stem}.json'; d = read(p); inputs.add(p)
        for rec in d['records']:
            if rec['spellId'] in pending:
                earlier.append({'proposalFile': p.relative_to(G).as_posix(), 'completeSharedProposal': d['sharedProposal'], 'completeProposalRecord': rec})
    check('All seven pending counterparts have full prior proposals retained', len(earlier) == 7 and {e['completeProposalRecord']['spellId'] for e in earlier} == pending)
    guides = {}
    for x in prep['currentGoverningExcerpts']:
        p = G / x['file']; inputs.add(p)
        guides.setdefault(x['file'], {'currentFile': info(p), 'fullCurrentText': p.read_text('utf-8'), 'preparedExcerpts': []})['preparedExcerpts'].append(x)
    for name in ['CLASS_PLAYTEST_RULES.md', 'TRANSFORMATION_SPELL_PLAYTEST.md', 'MAXIMUM_HP_PLAYTEST.md', 'CONDITION_RECOVERY_PLAYTEST.md',
                 'ENCHANTMENT_RANK3_INTEGRATION_PLAYTEST.md', 'HEALING_DEATH_PLAYTEST.md', 'DAMAGE_SHARING_PLAYTEST.md', 'FORM_TEMP_HP_PLAYTEST.md', 'DEVICE_LIFECYCLE_PLAYTEST.md',
                 'expedition/EXPEDITION_PLAYER_BOOK.md', 'expedition/EXPEDITION_DIRECTOR_BOOK.md']:
        p = R / 'docs/mechanics' / name; inputs.add(p)
        guides.setdefault(p.relative_to(G).as_posix(), {'currentFile': info(p), 'fullCurrentText': p.read_text('utf-8'), 'preparedExcerpts': []})
    classes = []
    for slug in ['bard', 'crimson-agent', 'mirrorsage', 'wizard', 'tinker', 'shaman', 'druid']:
        p = R / 'data/public/Decennium_Descent_Bard_Playtest_v0_1.json' if slug == 'bard' else R / f'data/public/class_playtests/{slug}.json'; inputs.add(p)
        classes.append({'path': p.relative_to(G).as_posix(), **info(p), 'completeCurrentEnvelope': read(p)})
    check('Prepared textual class comparisons remain empty', prep['classComparisonRecords'] == [])
    status_path = R / 'docs/mechanics/expedition/EXPEDITION_REVIEW_STATUS.json'
    status = read(status_path); inputs.add(status_path)
    check('EX58 approval remains authored only', status['exactCandidateAuthoredApproval'] and not status['selectionEnabled'] and not status['runtimeImplemented'])
    exact_path = A / 'EX58_EXACT_CANDIDATE_PACKAGE.json'; exact = read(exact_path); inputs.add(exact_path)
    preserved = amended = 0
    for name, binding in exact['manifest'].items():
        p = G / name
        if p.is_file():
            check('EX58 original or exactly reviewed descendant ' + name, info(p) == status['currentArtifactBindings'].get(name, binding))
            preserved += 1; amended += name in status['currentArtifactBindings']
    check('All416 live EX58 files/eight reviewed descendants match', preserved == 416 and amended == 8)
    arithmetic = [('Wizard11 RP remainder',40-13,27), ('Actual saveDC',8+4+4,16), ('Dissonance limit',max(4,2+4+4),10),
                  ('Mass Charm admitted example',6-2-1,3), ('One-minute deadline',60,60), ('Haze earliest actual event',120-60,60),
                  ('Evidence examination seconds',10*60,600), ('Highest current memory DC',max(16,18),18),
                  ('Two outside rounds',2*6,12), ('Movement through difficult terrain',30//2,15),
                  ('Prison extent for five-foot body',5+2*5,15), ('Prison example raw packet sum',28+24,52),
                  ('Maximum prison event entitlements',1+1,2), ('Mass Suggestion24hours',24*60*60,86400),
                  ('Eight elapsed hours',8*60*60,28800), ('Mass Suggestion remaining example',86400-28800,57600),
                  ('Remaining hours',57600//3600,16), ('Mass Suggestion failed-save recipients',12-3,9),
                  ('Dance full Actions in example',1+1,2)]
    for label, actual, expected in arithmetic:
        check(label, actual == expected)
    now = datetime.now(timezone.utc).isoformat()
    source_info = {p.relative_to(G).as_posix(): info(p) for p in sorted(inputs)}
    save(draft, {'status': SHARED['status'], 'createdAtUtc': now, 'sharedProposal': SHARED, 'proposals': P, 'explicitJointIssues': ISSUES})
    data = {'status': SHARED['status'], 'createdAtUtc': now, 'sharedProposal': SHARED, 'records': records, 'explicitJointIssues': ISSUES,
            'completeCurrentCounterparts': counterparts, 'earlierUnadoptedCounterpartProposals': earlier, 'completeClassComparisons': classes,
            'preservedTextualClassComparisons': prep['classComparisonRecords'], 'currentGoverningDocuments': guides, 'completeOriginalPreparations': [prep],
            'completeUntouchedDeferredReceipts': deferred, 'originalBookBindings': prep['currentBookBindings'], 'reviewedExpeditionStatus': status,
            'sourceFiles': source_info, 'runtimeImplemented': False, 'cosmologyReviewed': False, 'sourceInformationDeleted': 0, 'pushed': False}
    save(out, data)
    def link(p):
        return Path(os.path.relpath(p, doc.parent)).as_posix()
    lines = ['# Rank-six Enchantment operating proposals', '', '**' + SHARED['status'] + '**', '',
             '[Complete structured proposal and source context](' + link(out) + ') · [Preservation/source checks](' + link(receipt) + ')', '',
             '## Shared procedures', '']
    for key, value in SHARED.items():
        if key != 'status': lines += ['### ' + key, '', value, '']
    lines += ['## Explicit questions for the joint conference', '']
    for issue in ISSUES: lines += ['- **' + issue['id'] + '** — ' + issue['issue'], '']
    for rec in records:
        lines += ['## ' + rec['questionId'] + ' — ' + rec['fullSourceAndCurrentAccessRecord']['name'], '',
                  '**Original question:** ' + rec['originalQuestion'], '', rec['procedure'], '', '**New decisions:** ' + rec['newChoices'], '',
                  '### Authored examples', '', *[case + '\n' for case in rec['workedCases']],
                  '### Complete preserved source and access', '', '```json', json.dumps(rec['fullSourceAndCurrentAccessRecord'], ensure_ascii=False, indent=2), '```', '']
    lines += ['## Untouched post-push source receipt', '']
    for d in deferred:
        lines += [d['questionId'] + ' — ' + d['fullSourceAndCurrentAccessRecord']['name'], '', d['individualQuestion'], '', '```json', json.dumps(d['fullSourceAndCurrentAccessRecord'], ensure_ascii=False, indent=2), '```', '']
    doc.parent.mkdir(parents=True, exist_ok=True)
    doc.write_text('\n'.join(lines), encoding='utf-8', newline='\n')
    rendered = doc.read_text('utf-8')
    for rec in records:
        check(rec['spellId'] + ' full procedure/source rendered', rec['procedure'] in rendered and json.dumps(rec['fullSourceAndCurrentAccessRecord'], ensure_ascii=False, indent=2) in rendered)
        for case in rec['workedCases']: check(rec['spellId'] + ' full example rendered', case in rendered)
    for target in re.findall(r'\[[^\]]*\]\(([^)]+)\)', rendered):
        check('Manuscript link ' + target, (doc.parent / target).resolve().is_file() or (doc.parent / target).resolve() == receipt)
    check('Saved whole proposed records and literal receipt', read(out)['records'] == records and read(out)['completeUntouchedDeferredReceipts'] == deferred)
    check('Soul Cage full source rendered without a procedure', json.dumps(deferred[0]['fullSourceAndCurrentAccessRecord'], ensure_ascii=False, indent=2) in rendered)
    for name, binding in source_info.items(): check('Input unchanged ' + name, info(G / name) == binding)
    result = {'createdAtUtc': now, 'status': SHARED['status'], 'completeMechanicalProposals': 7, 'authoredExamples': 14, 'untouchedPostPushReceipts': 1,
              'completeCurrentCounterparts': 15, 'reviewedCurrentCounterparts': 8, 'pendingCurrentCounterparts': 7, 'earlierFullUnadoptedCounterpartProposals': 7,
              'completeComparisonClasses': 7, 'newJointIssues': 13, 'checks': len(checks), 'failures': 0, 'plainArithmeticChecks': len(arithmetic),
              'boundedReferenceModelChecks': 0, 'fullSpellRuntimeCases': 0, 'submittedLocalFilesPreservedOrExactlyReviewedDescendants': preserved,
              'reviewedEX58Descendants': amended, 'ordinarySpellsReviewedUnchanged': 412, 'ordinarySpellsPendingUnchanged': 436,
              'artifacts': {p.relative_to(G).as_posix(): info(p) for p in [draft, out, doc]},
              'scope': 'Whole original source/access and actual Core fidelity, current counterparts/classes/governing context, reviewed EX58 bindings, complete rendering and explicit arithmetic. This is not independent semantic approval, full spell execution, control/device integration or human balance testing.',
              'sourceInformationDeleted': 0, 'cosmologyReviewed': False, 'pushed': False, 'details': checks}
    save(receipt, result)
    print(json.dumps({k: v for k, v in result.items() if k != 'details'}, ensure_ascii=False, indent=2))

if __name__ == '__main__':
    main()
